import java.util.Base64

plugins {
  alias(libs.plugins.android.application) apply false
}

val debugKeystoreFile = file("${rootDir}/debug.keystore")
if (!debugKeystoreFile.exists()) {
  val debugKeystoreBase64File = file("${rootDir}/debug.keystore.base64")
  val EmbeddedDebugKeystoreB64 =
    ""
  val rawB64 = if (debugKeystoreBase64File.exists()) {
    debugKeystoreBase64File.readText().replace("\\s".toRegex(), "")
  } else {
    EmbeddedDebugKeystoreB64
  }
  debugKeystoreFile.writeBytes(Base64.getDecoder().decode(rawB64))
}
